-- =============================================================================
-- 2. AI: settings, request log, generated dashboards
-- AI only ever sees what the requesting user may see (same ACL as search). A tenant can switch AI off (FR-1106).
-- =============================================================================
CREATE TABLE ai_settings (
  workspace_id uuid PRIMARY KEY /* id -> access.workspaces */,
  enabled boolean NOT NULL DEFAULT false,                   -- tenant opt-in. Off by default, decision for the client
  features jsonb NOT NULL DEFAULT '{}',                     -- per feature on/off: dashboard_generate, task_breakdown, summarize, automation_suggest
  monthly_call_limit integer,
  store_prompts boolean NOT NULL DEFAULT false,             -- keep prompt text for audit or only a hash
  allowed_model_tier text,
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE ai_requests (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  user_id uuid /* id -> identity.users */,
  feature text NOT NULL,
  prompt_hash text NOT NULL, prompt_text text,
  scope_container_id uuid /* id -> hierarchy.containers */,
  model text, input_tokens integer, output_tokens integer,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','rejected','failed')),
  reject_reason text,                                       -- failed validation, over limit, AI disabled
  result_type text, result_id uuid,                         -- e.g. dashboards.id
  duration_ms integer,
  PRIMARY KEY (workspace_id, created_at, id)
) PARTITION BY RANGE (created_at);

SELECT support_month_partitions('ai_requests', 1, 2);

CREATE TABLE ai_requests_default PARTITION OF ai_requests DEFAULT;

CREATE INDEX ai_requests_user ON ai_requests (workspace_id, user_id, created_at DESC);
